    // ----- Dépôt : capacité de cassette, borne incluse -----

    public static TheoryData<NoteCounts, NoteCounts> DepositsFillingACassetteExactly => new()
    {
        { new(4, 0, 0), new(1, 0, 0) },
        { new(0, 4, 0), new(0, 1, 0) },
